/*
Package types holds the HTTP wire contract.

This package is the single source of truth for the shapes the frontend sees.
`make types` runs tygo over it to regenerate web/lib/api-types.ts, so a field
rename here becomes a TypeScript compile error there instead of a runtime
surprise during a live webinar.

Keep these boring: scalars, slices, maps and other types from this package.
No interfaces, no generics, no embedded structs from other packages.
*/

/**
 * Role decides what a participant may do inside a room. This is the entire
 * difference between a webinar and a meeting.
 */
export type Role = string;
export const RoleHost: Role = "host";
export const RolePanelist: Role = "panelist";
export const RoleAttendee: Role = "attendee";
export type WebinarStatus = string;
export const StatusScheduled: WebinarStatus = "scheduled";
export const StatusLive: WebinarStatus = "live";
export const StatusEnded: WebinarStatus = "ended";
export const StatusDraft: WebinarStatus = "draft";
export type WebinarKind = string;
export const KindLive: WebinarKind = "live";
export const KindSimulive: WebinarKind = "simulive";
export const KindRecurring: WebinarKind = "recurring";
export type ApprovalMode = string;
export const ApprovalAutomatic: ApprovalMode = "automatic";
export const ApprovalManual: ApprovalMode = "manual";
export type RegistrationState = string;
export const RegApproved: RegistrationState = "approved";
export const RegPending: RegistrationState = "pending";
export const RegDeclined: RegistrationState = "declined";
/**
 * NotificationKind is why somebody is being told something.
 */
export type NotificationKind = string;
/**
 * NotifyApprovalRequested goes to the HOST: somebody is waiting for a decision.
 */
export const NotifyApprovalRequested: NotificationKind = "approval_requested";
/**
 * NotifyRegistrationApproved goes to the REGISTRANT, with their join link.
 */
export const NotifyRegistrationApproved: NotificationKind = "registration_approved";
/**
 * NotifyRegistrationDeclined goes to the REGISTRANT. Sent rather than silently
 * dropped: somebody who registered and hears nothing assumes they are coming.
 */
export const NotifyRegistrationDeclined: NotificationKind = "registration_declined";
/**
 * NotifyRegistrationConfirmed is auto-approve signup: they are in without a host review.
 */
export const NotifyRegistrationConfirmed: NotificationKind = "registration_confirmed";
/**
 *  NotifyReminder is one timed email reminder. A webinar has up to MaxReminders of them,
 * 	 * each ReminderOffsetMin before its start (WebinarOptions.Reminders), so the offset is
 * 	 * on the row and uniqueness is (kind, registration, offset). Replaced reminder_24h and
 * 	 * reminder_1h, which fixed the two times in the kind itself (migration 0052).
 */
export const NotifyReminder: NotificationKind = "reminder";
/**
 *  The same three things said on WhatsApp, which are separate kinds rather than
 * 	 * the same kinds on another channel. A host may well want both — an email with
 * 	 * a calendar file and a message on the phone the person will actually be
 * 	 * holding — and one kind per row is what lets the outbox guarantee one of each
 * 	 * per registration.
 */
export const NotifyWhatsAppConfirmed: NotificationKind = "wa_registration_confirmed";
/**
 *  NotifyWhatsAppReminder is the same timed reminder on WhatsApp: one template for every
 * 	 * time, chosen once by the host, with the `starts_in` merge field for "in 30 minutes".
 */
export const NotifyWhatsAppReminder: NotificationKind = "wa_reminder";
/**
 *  NotifyWhatsAppBroadcast is one recipient of one broadcast: the host's own
 * 	 * message, written once and queued per person, rather than anything this
 * 	 * application decided to send. It is not in WhatsAppReminderKinds because it has
 * 	 * no settings row — the template and its values belong to the broadcast.
 */
export const NotifyWhatsAppBroadcast: NotificationKind = "wa_broadcast";
/**
 *  NotifyWhatsAppDrip is one step of one person's sequence, queued when it comes
 * 	 * due rather than all at once — the next step's time is only known once the
 * 	 * previous one has actually gone. Also not in WhatsAppReminderKinds: the template
 * 	 * belongs to the step, and nothing about a webinar's clock may reschedule it.
 */
export const NotifyWhatsAppDrip: NotificationKind = "wa_drip";
/**
 *  NotifyReplayReady is the email that says the recording is up, with the link to
 * 	 * watch it. Sent when the host shares one, not when it finishes processing: a
 * 	 * replay link that arrives before anybody has decided to publish it would hand out
 * 	 * a recording the host has not looked at yet.
 */
export const NotifyReplayReady: NotificationKind = "replay_ready";
/**
 *  NotifyWhatsAppReplay is the same sentence on WhatsApp, and it is in
 * 	 * WhatsAppReminderKinds because it works the way the other automatic messages do:
 * 	 * the host picks an approved template for it once, and it is sent to the people
 * 	 * who registered for the webinar it belongs to.
 */
export const NotifyWhatsAppReplay: NotificationKind = "wa_replay";
/**
 *  NotifyWelcome is the one thank-you email a new account gets, from signup or a first
 * 	 * Google sign-in. Addressed by email, never user_id, so it is not a host alert; one
 * 	 * per address, enforced by a unique index (migration 0058).
 */
export const NotifyWelcome: NotificationKind = "welcome";
/**
 *  The panelist's side of a webinar: added to the stage (with the stage link and a
 * 	 * calendar file), the start moved, the session cancelled. Addressed by email and tied to
 * 	 * no registration — a panelist signs in rather than holding a join key, so the link in
 * 	 * these is the same for every panelist and is not a credential. One invite per panelist
 * 	 * per webinar (migration 0070); updates and cancellations are one per change.
 */
export const NotifyPanelistInvited: NotificationKind = "panelist_invited";
